test("the shipped views.json is valid: Azure projects, each with a team with Sprint and Backlog and its pull requests, and a GitHub owner with a project, its number alone, and its PR list", () => {
  const { config, errors } = board.readConfig(shippedConfig());
  assert.deepEqual(errors, []);
  assert.match(config.azure.org, /^https:\/\/dev\.azure\.com\/[^/]+$/);
  assert.ok(config.azure.contexts.length >= 2);
  for (const context of config.azure.contexts) {
    assert.deepEqual(context.tabs.map((c) => [c.kind, c.views ?? null, c.project]), [["team", ["sprint", "backlog"], context.project], ["prs", null, context.project]]);
  }
  assert.equal(config.github.contexts.length, 1);
  assert.deepEqual(config.github.contexts[0].tabs.map((v) => [v.entryKind, v.name ?? null, v.source, v.layout ?? null]), [
    ["project", null, "github", null],
    ["issues", "Issues", "github", null],
    ["prs", "PRs", "github", "list"],
  ]);
  const [mine, issues, prs] = config.github.contexts[0].tabs;
  assert.deepEqual([issues.id, issues.hideRepos, JSON.parse(shippedConfig()).sources.github.contexts[0].issues], ["github:issues:issues", [], { id: "issues" }], "its Issues tab shows all its repos");
  assert.equal(mine.owner, config.github.contexts[0].owner);
  assert.deepEqual(JSON.parse(shippedConfig()).sources.github.contexts[0].projects, [{ number: mine.number }], "a project is its number alone: the rest comes from GitHub");
  assert.match(prs.sections.map((s) => s.query).join(" "), /author:@me/);
  assert.match(prs.sections.map((s) => s.query).join(" "), /review-requested:@me/);
  const raw = JSON.parse(shippedConfig()).sources.github;
  assert.deepEqual([raw.contexts[0].prs, raw.prs.sections.map((s) => s.name)], [{ id: "prs", name: "PRs" }, ["Zu prüfen", "Meine", "Geprüft"]],
    "its PR tab keeps the id prs, the sections stand shared in sources.github.prs");
});

test("no person-specific value of views.json appears in main.js", () => {
  const raw = JSON.parse(shippedConfig());
  const values = new Set();
  const add = (v) => typeof v === "string" && v.length > 3 && values.add(v);
  for (const a of raw.sources.github.contexts) {
    add(a.owner);
    for (const p of a.projects) values.add(`number: ${p.number}`);
  }
  add(raw.sources.azure.org);
  add(raw.sources.azure.org.split("/").pop());
  for (const a of raw.sources.azure.contexts) {
    add(a.project);
    for (const t of a.teams) add(t.team);
  }
  for (const [repo, entry] of Object.entries(raw.repos ?? {})) {
    add(repo);
    add(repo.split("/")[0]);
    Object.values(entry).forEach(add);
  }
  for (const key of ["message", "review", "machine"]) add(raw.start?.[key]);
  const code = readFileSync(mainPath, "utf8");
  assert.ok(values.size >= 7, "the config names the person's values");
  for (const value of values) assert.ok(!code.includes(value), `main.js holds ${JSON.stringify(value)}`);
  // The agent as a value of the code, alone or first in a string; Claude
  // Code's folder (~/.claude), which the board reads, may stand in it.
  const agent = raw.start.agent;
  const statements = code.split("\n").filter((line) => !line.trim().startsWith("//")).join("\n");
  for (const quote of ['"', "'", "`"]) {
    for (const form of [`${quote}${agent}${quote}`, `${quote}${agent} `]) assert.ok(!statements.includes(form), `main.js holds ${form}`);
  }
});

