  assert.equal(host.files[MACHINE_FILE], text, "the migration writes nothing");
  assert.deepEqual([board.hiddenKey(MINE), board.hiddenKey(OTHER)].map((k) => memory.has(k)), [true, true], "and keeps the entries");
