  assert.deepEqual(["ansi9", "ansi11", "ansi13", "ansi14", "ansi15", "ansi8", "ansi4", "muted", "dim", null].map(board.chipTone),
    ["ansi1", "ansi3", "ansi5", "ansi6", "ansi15", "ansi8", "ansi4", "muted", "dim", null]);
