  assert.equal(over.b.navColumns(over.b.view())[sel.col]?.shown.some((c) => c.key === sel.key), true, `a card of the saved state, in its column: ${JSON.stringify(sel)}`);
  const { b, cx, host, st } = await bootBoard();
