  await host.answer("gh", { code: 1, stdout: "", stderr: "HTTP 502: Bad Gateway" }, isIssuesCall);
  await settle();
  const r = b.render();
  assert.deepEqual([st().data, b.modal, byId(r, "solo-repo"), byId(r, "choice-list-shield"), b.handle.held], [null, null, null, null, true]);
