  await host.answer("gh", ok(fixture("github-issues.json")), isIssuesCall);
  await press(b, cx, "v");
  const closed = json("github-issues-closed.json");
  closed.data.search.pageInfo = { hasNextPage: true, endCursor: "c1" };
